insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t'), 1, 'le-son-a', 'Le son a', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t') and slug = 'le-son-a'), $html$<p>Écoute bien : on entend le son <strong>[a]</strong> dans « ananas », « papa », « sac », « Awa ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>a · A</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>a · A</strong></p><p>Des mots : <strong>la · papa · Awa</strong></p><h2>J’écris</h2><p>Je trace un rond, puis un petit trait collé à droite : a.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [a].</li><li>Cherche [a] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t'), 2, 'le-son-i', 'Le son i', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t') and slug = 'le-son-i'), $html$<p>Écoute bien : on entend le son <strong>[i]</strong> dans « lit », « midi », « riz », « Ibrahima ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>i · I</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>i · a · ia</strong></p><p>Des mots : <strong>il · Ali · Awa</strong></p><h2>J’écris</h2><p>Je trace un petit trait vers le bas, puis je pose le point au-dessus : i.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [i].</li><li>Cherche [i] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t'), 3, 'le-son-t', 'Le son t', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-a-i-et-t') and slug = 'le-son-t'), $html$<p>Écoute bien : on entend le son <strong>[t]</strong> dans « tomate », « tableau », « tata », « Touba ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>t · T</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>ta · ti · at · it</strong></p><p>Des mots : <strong>tata · ta tata · Tati</strong></p><h2>J’écris</h2><p>Je trace un grand trait vers le bas, puis une petite barre : t.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [t].</li><li>Cherche [t] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
