insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-f-u-et-ou') and slug = 'le-son-u'), $html$<p>Écoute bien : on entend le son <strong>[u]</strong> dans « lune », « tortue », « jus », « pull ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>u · U</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tu · lu · nu · mu · bu · pu · du · fu</strong></p><p>Des mots : <strong>lune · plume · tutu · bulle</strong></p><p>Une phrase : <strong>Il a lu le menu.</strong></p><h2>J’écris</h2><p>Je trace un creux, puis un petit trait qui redescend : u.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [u].</li><li>Cherche [u] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-f-u-et-ou'), 3, 'le-son-ou', 'Le son ou', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-f-u-et-ou') and slug = 'le-son-ou'), $html$<p>Écoute bien : on entend le son <strong>[ou]</strong> dans « loup », « chou », « mouton », « Moussa ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>ou</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tou · lou · nou · mou · bou · pou · dou · fou</strong></p><p>Des mots : <strong>loup · poule · boule · moule · Doudou · Modou</strong></p><p>Une phrase : <strong>Modou a la boule de Doudou.</strong></p><h2>J’écris</h2><p>J’écris o, puis u, l’un contre l’autre : ou.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [ou].</li><li>Cherche [ou] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div><div class="callout"><p class="callout-title">Je retiens</p><p><strong>u</strong> et <strong>ou</strong> ne se disent pas pareil : « tu » n’est pas « tout ».</p></div>$html$);
insert into public.chapters (program_id, number, slug, title, summary, sort_order, status) values ((select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null), 11, 'les-sons-e-et-e', 'Les sons é et è', 'Entendre, lire et écrire é (é, et) et è (è, ê, ai, e).', 11, 'published');
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-e-et-e'), 1, 'le-son-e-comme-dans-bebe', 'Le son é, comme dans bébé', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-e-et-e') and slug = 'le-son-e-comme-dans-bebe'), $html$<p>Écoute bien : on entend le son <strong>[é]</strong> dans « bébé », « café », « école », « éléphant ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>é · et</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>té · lé · né · pé · dé · mé · bé · fé</strong></p><p>Des mots : <strong>bébé · été · le dé · la fée</strong></p><p>Une phrase : <strong>Papa et le bébé.</strong></p><h2>J’écris</h2><p>J’écris e, puis je pose un petit accent qui penche vers la droite : é.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [é].</li><li>Cherche [é] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-e-et-e'), 2, 'le-son-e-comme-dans-mere', 'Le son è, comme dans mère', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-e-et-e') and slug = 'le-son-e-comme-dans-mere'), $html$<p>Écoute bien : on entend le son <strong>[è]</strong> dans « mère », « fête », « lait », « élève ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>è · ê · ai · e (dans « elle »)</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tè · lè · mè · pè · fê · lai · mai</strong></p><p>Des mots : <strong>fête · tête · lait · elle · belle · même</strong></p><p>Une phrase : <strong>Maman fête le bébé.</strong></p><h2>J’écris</h2><p>Pour è, l’accent penche vers la gauche ; pour ê, il fait un petit chapeau.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [è].</li><li>Cherche [è] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
