insert into public.lessons (chapter_id, number, slug, title, is_premium, status, estimated_minutes, published_at) values ((select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on'), 1, 'le-son-s', 'Le son s', false, 'published', 10, now());
insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-s'), $html$<p>Écoute bien : on entend le son <strong>[s]</strong> dans « sac », « soleil », « salade », « Sokhna ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>s · S</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>sa · si · so · su · sou · sé · as · is</strong></p><p>Des mots : <strong>Sali · sous · soupe · salade</strong></p><p>Une phrase : <strong>Sali a salé la soupe.</strong></p><h2>J’écris</h2><p>Je trace un petit serpent : s.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [s].</li><li>Cherche [s] dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
