insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'les-sons-s-r-au-et-on') and slug = 'le-son-au'), $html$<p>Écoute bien : on entend le son <strong>[o] écrit au ou eau</strong> dans « auto », « bateau », « seau », « chaud ».</p><h2>Je le vois</h2><p>Il s’écrit : <strong>au · eau · o</strong>.</p><h2>Je lis</h2><p>Des syllabes : <strong>tau · lau · pau · beau · deau · seau</strong></p><p>Des mots : <strong>auto · bateau · seau · rideau · taureau</strong></p><p>Une phrase : <strong>Papa a un beau bateau.</strong></p><h2>J’écris</h2><p>J’écris a et u collés pour au ; e, a et u pour eau.</p><div class="example"><p class="callout-title">Avec un adulte, je m’entraîne</p><ul><li>L’adulte dit des mots. Tu frappes dans tes mains quand tu entends [o] écrit au ou eau.</li><li>Cherche [o] écrit au ou eau dans ton prénom, dans les prénoms de ta famille ou sur une affiche.</li><li>Lis les syllabes à voix haute, puis écris-en trois sur ton ardoise ou ton cahier.</li></ul></div>$html$);
