insert into public.lesson_bodies (lesson_id, body_html) values ((select id from public.lessons where chapter_id = (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'FR' and l.code = 'CI' and p.series_id is null) and c.slug = 'mes-premieres-lettres-attachees') and slug = 'les-lettres-rondes-o-c-a-d-q'), $html$<p>En écriture attachée, les lettres se tiennent la main. On commence par les lettres <strong>rondes</strong>.</p>
