insert into public.questions (slug, subject_id, chapter_id, type, prompt_html, explanation_html, points) values ('thales-q6', (select id from public.subjects where code = 'MATH'), (select c.id from public.chapters c where c.program_id = (select p.id from public.programs p join public.subjects s on s.id = p.subject_id join public.levels l on l.id = p.level_id where s.code = 'MATH' and l.code = '3E' and p.series_id is null) and c.slug = 'theoreme-de-thales'), 'short_text', $html$<p>Quel théorème permet de démontrer que deux droites sont parallèles à partir de rapports égaux ?</p>$html$, $html$<p>C’est la <strong>réciproque du théorème de Thalès</strong>.</p>$html$, 3);
